# Immutable source pins used to reset synthetic test-only overrides between fixtures.
TABLE012_TEMPLATE_ROOT = validator.TABLE012_ROOT
TRUSS011_TEMPLATE_ROOT = validator.TRUSS011_ROOT
TABLE012_TEMPLATE_SELECTED = dict(validator.TABLE012_SELECTED)
TRUSS011_TEMPLATE_SELECTED = dict(validator.TRUSS011_SELECTED)
TABLE012_TEMPLATE_SELECTED_BYTES = validator.TABLE012_SELECTED_BYTES
TRUSS011_TEMPLATE_SELECTED_BYTES = validator.TRUSS011_SELECTED_BYTES
TRUSS011_TEMPLATE_OUTPUT_BYTES = validator.TRUSS011_OUTPUT_BYTES

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def ref(root: Path, name: str, data: bytes) -> dict[str, object]:
    path = root / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
    return {"path": name, "sizeBytes": len(data), "sha256": sha(data)}


def json_ref(root: Path, name: str, value: dict) -> dict[str, object]:
    return ref(root, name, (json.dumps(value, sort_keys=True) + "\n").encode())


def rewrite_json_ref(root: Path, ref_value: dict, value: dict) -> None:
    raw = (json.dumps(value, sort_keys=True) + "\n").encode()
    (root / ref_value["path"]).write_bytes(raw)
    ref_value.update(sizeBytes=len(raw), sha256=sha(raw))


def git_blob_sha(data: bytes) -> str:
    return hashlib.sha1(b"blob " + str(len(data)).encode("ascii") + b"\0" + data).hexdigest()


def padded_json_bytes(value: dict, target: int) -> bytes:
    padding = ""
    for _ in range(32):
        value["_syntheticPadding"] = padding
        raw = (json.dumps(value, sort_keys=True) + "\n").encode()
        delta = target - len(raw)
        if delta == 0:
            return raw
        padding = (padding + "x" * delta) if delta > 0 else padding[:delta]
    raise AssertionError("could not close test-only JSON to source-pinned byte count")


def source_map(root: Path, role: str, commit: str, tree: str, changed: bool = False,
               metadata_contents: dict[str, bytes] | None = None,
               omit_paths: set[str] | None = None) -> tuple[dict, dict]:
    paths = [f"crates/input-{i:04d}" for i in range(1459)]
    required = ["docs/helix/05-deploy/README.md", "docs/helix/05-deploy/releases/v0.4.56.md",
                "docs/helix/05-deploy/local-release-runbook-0.4.56.md",
                "scripts/release/verify_local_release_profile.py",
                "scripts/release/publish_local_release.py",
                "scripts/release/test_verify_local_release_profile.py",
                "scripts/release/test_publish_local_release.py"]
    paths += [path for path in required if path not in (omit_paths or set())]
    paths += [f"docs/helix/05-deploy/meta-{i:04d}.md" for i in range(5901 - len(paths))]
    paths.sort()
    stage, tracked, selected = [], [], []
    metadata_contents = metadata_contents or {}
    for path in paths:
        content = metadata_contents.get(path, path.encode())
        if changed and path == "docs/helix/05-deploy/README.md":
            content = b"metadata-only"
        blob = git_blob_sha(content)
        mode = "100644"
        stage.append(f"{mode} {blob} 0\t{path}")
        tracked.append({"path": path, "mode": mode, "gitBlobSha1": blob})
        if path.startswith("crates/input-"):
            raw = path.encode()
            selected.append({"path": path, "bytes": len(raw), "sha256": sha(raw)})
    if changed:
        ix = paths.index("docs/helix/05-deploy/README.md")
        old = tracked[ix]["gitBlobSha1"]
        new = sha(b"metadata-only").zfill(40)[:40]
        tracked[ix]["gitBlobSha1"] = new
        stage[ix] = f"100644 {new} 0\t{paths[ix]}"
    selected_digest = sha((json.dumps(selected, sort_keys=True) + "\n").encode())
    path_digest = sha(("\n".join(paths) + "\n").encode())
    stage_digest = sha("\n".join(stage).encode())
    source = {"commit": commit, "tree": tree, "status": "", "trackedCount": len(paths),
              "trackedPathSha256": path_digest, "gitStageRosterSha256": stage_digest,
              "selectedInputCount": len(selected), "selectedInputRosterSha256": selected_digest,
              "version": "0.4.56"}
    value = {"profile": "weft-local-release-source-map/1", "source": source,
             "trackedPaths": paths, "stageRows": stage, "trackedFiles": tracked,
             "selectedBuildInputs": selected}
    return json_ref(root, f"receipts/{role}-source-map.json", value), value


class FullPacket:
    def __init__(self, root: Path):
        self.root = root
        self.patchers = []

    def _historical_files(self, root: Path, name: str) -> list[dict]:
        logs = root / "logs"
        logs.mkdir(parents=True, exist_ok=True)
        path = logs / name
        path.write_bytes(("test-only producer log " + name).encode())
        # Keep the producer-root copy and its receipt-relative counterpart.
        # The validator intentionally resolves files[] under the receipt root.
        receipt_copy = self.root / "receipts" / "logs" / name
        receipt_copy.parent.mkdir(parents=True, exist_ok=True)
        receipt_copy.write_bytes(path.read_bytes())
        return [{"path": "logs/" + name, "bytes": path.stat().st_size,
                 "sha256": sha(path.read_bytes())}]

    def _mac_producer_records(self, roots, commit, tree, filename, wheel_sha,
                              wheel_bytes, report, licenses, source_facts):
        build_root, audit_root = roots["macBuild"], roots["macAudit"]
        build_operator_root = roots["macBuildOperator"]
        audit_operator_root = roots["macAuditOperator"]
        source_root, custody_root = roots["macSource"], roots["macCustody"]
        py_path = roots["macPython"]
        source_identity = {"commit": commit, "tree": tree, "version": "0.4.56", "status": "",
            "trackedCount": source_facts["trackedCount"],
            "gitStageRosterSha256": source_facts["gitStageRosterSha256"],
            "selectedInputCount": source_facts["selectedInputCount"],
            "selectedInputRosterSha256": source_facts["selectedInputRosterSha256"]}
        build_operator_root.mkdir(parents=True, exist_ok=True)
        audit_operator_root.mkdir(parents=True, exist_ok=True)
        runner = build_operator_root / "run_build_static.py"; runner.write_bytes(b"test Mac build runner")
        build_audit = build_operator_root / "static_audit.py"; build_audit.write_bytes(b"test Mac build audit helper")
        audit_runner = audit_operator_root / "run_static_audit.py"; audit_runner.write_bytes(b"test Mac audit runner".ljust(22917, b" "))
        audit_helper = audit_operator_root / "static_audit.py"; audit_helper.write_bytes(b"test Mac audit helper")
        runner_sha, helper_sha = sha(runner.read_bytes()), sha(audit_runner.read_bytes())
        audit_helper_sha = sha(audit_helper.read_bytes())
        build_logs = {}
        for name, data in (("setup.json", b"test setup\n"),
                           ("logs/candidate-build.stdout.log", b""),
                           ("logs/candidate-build.stderr.log", b"build stderr\n"),
                           ("logs/static-audit.stdout.log", b""),
                           ("logs/static-audit.stderr.log", b"audit stderr\n")):
            path = build_root / name; path.parent.mkdir(parents=True, exist_ok=True); path.write_bytes(data)
            build_logs[name] = {"path": name, "bytes": len(data), "sha256": sha(data)}
        stages = []
        for label, stdout_name, stderr_name, exit_code in (
                ("candidate-build", "logs/candidate-build.stdout.log", "logs/candidate-build.stderr.log", 0),
                ("static-audit", "logs/static-audit.stdout.log", "logs/static-audit.stderr.log", 1)):
            physical = []
            for name in (stdout_name, stderr_name):
                row = build_logs[name]
                physical.append({"path": str(build_root / name), "bytes": row["bytes"], "sha256": row["sha256"]})
            stages.append({"name": label, "exitCode": exit_code, "physical": physical})
        build = {"profile": validator.MAC_ORIGINAL_BUILD_PROFILE,
            "status": validator.MAC_ORIGINAL_BUILD_STATUS, "executionKind": "local-build-only",
            "hosted": False, "installed": False, "candidate": None,
            "source": source_identity, "postRunSource": source_identity,
            "operator": {"acceptedPlanSha256": "cafc0eb9b3ed1346210e2e1b85e437df8fb85beb7bd70e5e454f992de5b5ac53",
                "measurementRepairPlanSha256": "fba4b31855acb8ab74a864ef4e5b84d080a52987d5e4a95ffe493c1d045b0ff4",
                "runnerPath": str(runner), "runnerBytes": runner.stat().st_size, "runnerSha256": runner_sha,
                "staticAuditPath": str(build_audit), "staticAuditBytes": build_audit.stat().st_size,
                "staticAuditSha256": sha(build_audit.read_bytes())},
            "postRunOperator": {"runnerBytes": runner.stat().st_size, "runnerSha256": runner_sha,
                "staticAuditBytes": build_audit.stat().st_size, "staticAuditSha256": sha(build_audit.read_bytes())},
            "selectedEvidenceFiles": list(build_logs.values()),
            "selectedEvidenceBytes": sum(row["bytes"] for row in build_logs.values()),
            "stages": stages, "cleanupErrors": []}
        # Build receipt's absolute historical result is copied after it is encoded by caller.
        audit_root.mkdir(parents=True, exist_ok=True)
        custody_root.mkdir(parents=True, exist_ok=True)
        custody = {}
        for name, content in (("custody.json", b"test custody"),
                              ("git-stage-roster.txt", b"test stage roster"),
                              ("source-inputs.rows.json", b"test source inputs")):
            path = custody_root / name; path.write_bytes(content)
            custody[name] = {"bytes": len(content), "path": str(path), "sha256": sha(content)}
        inputs = {"count": source_identity["selectedInputCount"],
                  "rosterSha256": source_identity["selectedInputRosterSha256"], "totalBytes": 12345}
        original_source = {"commit": commit, "tree": tree,
            "selectedInputCount": source_identity["selectedInputCount"],
            "selectedInputRosterSha256": source_identity["selectedInputRosterSha256"],
            "sourceInputsBefore": inputs, "sourceInputsAfter": inputs,
            "custodyAssetsBefore": custody, "custodyAssetsAfter": custody}
        audit_logs = {}
        for name, content in (("logs/static-audit.stdout.log", b"static audit stdout\n"),
                              ("logs/static-audit.stderr.log", b"")):
            path = audit_root / name; path.parent.mkdir(parents=True, exist_ok=True); path.write_bytes(content)
            audit_logs[name] = {"path": name, "bytes": len(content), "sha256": sha(content)}
        report_raw = (json.dumps(report, sort_keys=True) + "\n").encode()
        static_path = audit_root / "static-audit.json"; static_path.write_bytes(report_raw)
        static_fact = {"path": "static-audit.json", "bytes": len(report_raw), "sha256": sha(report_raw)}
        selected = [static_fact, *audit_logs.values()]
        capture_physical = [{"path": str(audit_root / row["path"]), "bytes": row["bytes"],
                             "sha256": row["sha256"]} for row in audit_logs.values()]
        wheel_path = build_root / "dist" / filename
        capture = {"argv": [str(py_path), str(audit_helper), str(wheel_path), str(static_path), str(source_root)],
            "cwd": str(source_root), "limitSeconds": 120, "effectiveDeadlineSeconds": 1.0,
            "exitCode": 0, "captureVerified": True, "timedOut": False, "drainExpired": False,
            "captureErrors": [], "paths": [row["path"] for row in capture_physical],
            "rawSha256": [row["sha256"] for row in capture_physical],
            "retainedSha256": [row["sha256"] for row in capture_physical],
            "retainedBytes": [row["bytes"] for row in capture_physical],
            "truncated": [False, False], "physical": capture_physical}
        audit = {"profile": validator.MAC_AUDIT_PROFILE,
            "status": "LOCAL_MACOS_STATIC_AUDIT_ONLY_PASS", "executionKind": "local-static-audit-only",
            "hosted": False, "installed": False, "imported": False, "nativeExecuted": False,
            "browserParity": False, "compilerParity": False, "functionalQualification": "NOT_RUN",
            "failure": None, "cleanupErrors": [], "closureErrors": [],
            "operator": {"runnerPath": str(audit_runner),
                "runnerBefore": [audit_runner.stat().st_size, helper_sha],
                "runnerAfter": [audit_runner.stat().st_size, helper_sha],
                "helper": {"path": str(audit_helper), "bytes": audit_helper.stat().st_size,
                           "sha256": audit_helper_sha},
                "helperAfter": [audit_helper.stat().st_size, audit_helper_sha],
                "pythonPath": str(py_path), "pythonBefore": [py_path.stat().st_size, sha(py_path.read_bytes())],
                "pythonAfter": [py_path.stat().st_size, sha(py_path.read_bytes())]},
            "originalInputs": {"result": {"path": str(build_root / "result.json"),
                "bytes": 0, "sha256": "0"*64, "before": [0, "0"*64], "after": [0, "0"*64]},
                "source": original_source,
                "wheel": {"path": str(wheel_path), "bytes": wheel_bytes, "sha256": wheel_sha}},
            "wheelBefore": [wheel_bytes, wheel_sha], "wheelAfter": [wheel_bytes, wheel_sha],
            "staticReport": {"path": str(static_path), "bytes": len(report_raw), "sha256": sha(report_raw)},
            "capture": capture, "limits": {"aggregateSeconds": 180, "auditSeconds": 120,
                "terminalReserveSeconds": 60, "aggregateLogBytes": validator.MAX_RAW_LOGS,
                "metadataBytes": validator.MAX_EVIDENCE_TOTAL},
            "selectedEvidenceFiles": selected,
            "selectedEvidenceBytes": sum(row["bytes"] for row in selected)}
        return build, audit

    @staticmethod
    def _pad_receipt(root: Path, ref_value: dict, target_bytes: int) -> dict:
        path = root / ref_value["path"]
        value = json.loads(path.read_text())
        raw = padded_json_bytes(value, target_bytes)
        path.write_bytes(raw)
        ref_value.update(sizeBytes=len(raw), sha256=sha(raw))
        return value

    @staticmethod
    def _copy_mac_audit_outputs(roots, receipt_parent: Path, report):
        for name in ("static-audit.json", "logs/static-audit.stdout.log", "logs/static-audit.stderr.log"):
            source = roots["macAudit"] / name
            target = receipt_parent / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(source.read_bytes())

    @staticmethod
    def _decode_operator_template(encoded: str) -> dict:
        return json.loads(zlib.decompress(base64.b64decode(encoded)))

    def _install_original_operator_fixtures(self, gate_refs: dict,
                                            producer_commit: str,
                                            producer_tree: str,
                                            producer_stage_sha256: str) -> dict:
        """Synthesize portable native-schema evidence from compact accepted templates."""
        validator.TABLE012_ROOT = TABLE012_TEMPLATE_ROOT
        validator.TRUSS011_ROOT = TRUSS011_TEMPLATE_ROOT
        validator.TABLE012_SELECTED = dict(TABLE012_TEMPLATE_SELECTED)
        validator.TRUSS011_SELECTED = dict(TRUSS011_TEMPLATE_SELECTED)
        validator.TABLE012_SELECTED_BYTES = TABLE012_TEMPLATE_SELECTED_BYTES
        validator.TRUSS011_SELECTED_BYTES = TRUSS011_TEMPLATE_SELECTED_BYTES
        validator.TRUSS011_OUTPUT_BYTES = TRUSS011_TEMPLATE_OUTPUT_BYTES
        validator.TABLE012_SOFTWARE_ROOT = TABLE012_TEMPLATE_ROOT
        validator.TRUSS011_SOFTWARE_ROOT = TRUSS011_TEMPLATE_ROOT
        validator.TRUSS011_BROWSER_EXPECTED = {
            "facts": dict(validator.TRUSS011_BROWSER_EXPECTED["facts"]),
            "entity": dict(validator.TRUSS011_BROWSER_EXPECTED["entity"])}
        table_receipt = self._decode_operator_template(TABLE012_RECEIPT_TEMPLATE_B64)
        # This portable fixture reuses the accepted receipt's native schema and
        # predicates, but its synthetic P source map has its own trusted test pins.
        # Rebind every native P56 identity field consistently before hashing the
        # synthesized receipt; production pins remain untouched.
        actual_table_commit = table_receipt["source"]["commit"]
        actual_table_tree = table_receipt["source"]["tree"]
        actual_stage_sha256 = table_receipt["sourceCustody"]["stageBasis"]["sha256"]
        def rebind_table_identity(value):
            if isinstance(value, dict):
                return {key: rebind_table_identity(item) for key, item in value.items()}
            if isinstance(value, list):
                return [rebind_table_identity(item) for item in value]
            if value == actual_table_commit:
                return producer_commit
            if value == actual_table_tree:
                return producer_tree
            if value == actual_stage_sha256:
                return producer_stage_sha256
            return value
        table_receipt = rebind_table_identity(table_receipt)
        truss_receipt = self._decode_operator_template(TRUSS011_RECEIPT_TEMPLATE_B64)
        actual_truss_stage_sha256 = truss_receipt["sourcePost"]["gitStageRoster"]["sha256"]
        def rebind_truss_stage(value):
            if isinstance(value, dict):
                return {key: rebind_truss_stage(item) for key, item in value.items()}
            if isinstance(value, list):
                return [rebind_truss_stage(item) for item in value]
            if value == actual_truss_stage_sha256:
                return producer_stage_sha256
            return value
        truss_receipt = rebind_truss_stage(truss_receipt)
        fixtures = (
            ("table012", TABLE012_TEMPLATE_ROOT, table_receipt,
             "linux-inherited-boundaries", "TABLE012"),
            ("truss011", TRUSS011_TEMPLATE_ROOT, truss_receipt,
             "linux-browser", "TRUSS011"),
        )
        roots, digests, review_digests = {}, {}, {}
        expected_lanes = {}
        for label, original_root, receipt_value, gate_name, prefix in fixtures:
            root = self.root / "receipts" / label
            root.mkdir(parents=True, exist_ok=True)
            rows = (receipt_value["publicFiles"] if label == "table012" else
                    [row for row in receipt_value["outputFiles"]
                     if row["path"] not in TRUSS011_TEMPLATE_SELECTED])
            row_by_path = {row["path"]: row for row in rows}
            special = {}
            if label == "truss011":
                for lane, count in (("facts", 5), ("entity", 33)):
                    facts = receipt_value["browserInputCustodyBeforeAfter"][lane]
                    cases = [{"id": case_id, "requestSha256": sha((case_id + " request").encode()),
                              "expectedSha256": sha((case_id + " expected").encode()),
                              "actualSha256": sha((case_id + " expected").encode())}
                             for case_id in facts["caseIds"]]
                    wasm_sha = sha(b"synthetic selected wasm\n")
                    receipts = {"cases": cases}
                    summary = {"cases": count, "nodeGlobals": False, "byteParity": True,
                        "wasmSha256": wasm_sha, "networkRequests": [
                            "http://weft.spike.test/", "http://weft.spike.test/spike.wasm",
                            "http://weft.spike.test/spike.js", "http://weft.spike.test/wrapper.js"]}
                    report = [{"id": case_id} for case_id in facts["caseIds"]]
                    for rel, value in ((f"browser-{lane}/receipts.json", receipts),
                                       (f"browser-{lane}/summary.json", summary),
                                       (f"owned/out/reports/{lane}.json", report)):
                        row = row_by_path[rel]
                        raw = (json.dumps(value, sort_keys=True, separators=(",", ":"))).encode()
                        target_size = row["sizeBytes"]
                        if len(raw) > target_size:
                            raise AssertionError(f"synthetic {rel} exceeds its schema-pinned size")
                        special[rel] = raw + b" " * (target_size - len(raw))
                selected_root = self.root / "external" / "truss011"
                selected_map = {}
                selected_rows = []
                for index, rel in enumerate(sorted(TRUSS011_TEMPLATE_SELECTED)):
                    content = f"synthetic truss runtime file {index}\n".encode()
                    selected_map[rel] = (len(content), sha(content))
                    selected_rows.append({"path": rel, "sizeBytes": len(content), "sha256": sha(content)})
                    dest = selected_root / rel
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    dest.write_bytes(content)
                validator.TRUSS011_SOFTWARE_ROOT = selected_root
                validator.TRUSS011_SELECTED = selected_map
                validator.TRUSS011_SELECTED_BYTES = sum(size for size, _ in selected_map.values())
                receipt_value["selectedSoftwareArtifactsBeforeBrowser"] = {
                    "files": [{"path": row["path"].removeprefix("owned/out/artifacts/"),
                               "sizeBytes": row["sizeBytes"], "sha256": row["sha256"]}
                              for row in selected_rows],
                    "totalBytes": validator.TRUSS011_SELECTED_BYTES}
                receipt_value["selectedSoftwareArtifactsAfterBrowser"] = json.loads(
                    json.dumps(receipt_value["selectedSoftwareArtifactsBeforeBrowser"]))
                by_path = {row["path"]: row for row in receipt_value["outputFiles"]}
                for selected_row in selected_rows:
                    by_path[selected_row["path"]].update(
                        sizeBytes=selected_row["sizeBytes"], sha256=selected_row["sha256"])
                # Bind every native physical-evidence row to the final synthetic
                # output roster by its original-root-relative path. This includes
                # selected software rows, whose size and digest both change in
                # this portable fixture.
                physical_bindings = receipt_value.get("physicalEvidenceBindings")
                if not isinstance(physical_bindings, list):
                    raise AssertionError("Truss template physical-evidence bindings are absent")
                for binding in physical_bindings:
                    if not isinstance(binding, dict) or not isinstance(binding.get("path"), str):
                        raise AssertionError("Truss template physical-evidence binding is malformed")
                    try:
                        original_relative = Path(binding["path"]).relative_to(
                            original_root.resolve()).as_posix()
                    except ValueError as exc:
                        raise AssertionError("Truss template binding escapes original root") from exc
                    output_row = by_path.get(original_relative)
                    if output_row is None:
                        raise AssertionError(
                            f"Truss template binding has no output row: {original_relative}")
                    binding["sizeBytes"] = output_row["sizeBytes"]
                    binding["sha256"] = output_row["sha256"]
                receipt_value["outputBytes"] = validator.TRUSS011_METADATA_BYTES + validator.TRUSS011_SELECTED_BYTES
                validator.TRUSS011_OUTPUT_BYTES = receipt_value["outputBytes"]
                for lane in ("facts", "entity"):
                    summary_path = f"browser-{lane}/summary.json"
                    summary_value = json.loads(special[summary_path])
                    # The JSON has a fixed row size and only trailing whitespace.
                    summary_value["wasmSha256"] = selected_map[
                        "owned/out/artifacts/truss-web/weft_wasm_bg.wasm"][1]
                    row = row_by_path[summary_path]
                    raw = json.dumps(summary_value, sort_keys=True, separators=(",", ":")).encode()
                    special[summary_path] = raw + b" " * (row["sizeBytes"] - len(raw))
                    facts = receipt_value["browserInputCustodyBeforeAfter"][lane]
                    facts["browserReceiptsSha256"] = sha(special[f"browser-{lane}/receipts.json"])
                    facts["postBrowserReceiptsSha256"] = facts["browserReceiptsSha256"]
                    facts["browserSummarySha256"] = sha(special[summary_path])
                    facts["postBrowserSummarySha256"] = facts["browserSummarySha256"]
                    native_path = f"owned/out/reports/{lane}.json"
                    facts["nativeReportSha256"] = sha(special[native_path])
                    facts["postBrowserNativeReportSha256"] = facts["nativeReportSha256"]
                    expected_lanes[lane] = {
                        "browserReceiptsSha256": facts["browserReceiptsSha256"],
                        "browserSummarySha256": facts["browserSummarySha256"],
                        "corpusBytes": facts["corpusBytes"],
                        "corpusSha256": facts["corpusSha256"],
                        "nativeReportBytes": len(special[native_path]),
                        "nativeReportSha256": facts["nativeReportSha256"]}
            else:
                selected_root = self.root / "external" / "table012"
                selected_map = {}
                for index, rel in enumerate(sorted(TABLE012_TEMPLATE_SELECTED)):
                    content = f"synthetic table runtime file {index}\n".encode()
                    selected_map[rel] = (len(content), sha(content))
                    dest = selected_root / rel
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    dest.write_bytes(content)
                validator.TABLE012_SOFTWARE_ROOT = selected_root
                validator.TABLE012_SELECTED = selected_map
                validator.TABLE012_SELECTED_BYTES = sum(size for size, _ in selected_map.values())
                receipt_value["selectedArtifactBytes"] = validator.TABLE012_SELECTED_BYTES
                for row in receipt_value["selectedArtifacts"]:
                    size, digest = selected_map[row["path"]]
                    row.update(sizeBytes=size, sha256=digest)
            # The native metadata file sizes stay exact, while deterministic content
            # and all capture/hash references are synthesized under this temp root.
            original_prefix = str(original_root)
            historical_copy_root = self.root / "historical" / f"{label}-output"
            new_prefix = str(historical_copy_root)
            for row in rows:
                rel = row["path"]
                size = row["sizeBytes"]
                data = special.get(rel, b"x" * size)
                if len(data) != size:
                    raise AssertionError(f"synthetic file size drift: {rel}")
                row["sha256"] = sha(data)
                target = root / rel
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(data)
            # Map original per-file hashes from the frozen template to synthetic bytes.
            old_rows = (self._decode_operator_template(TABLE012_RECEIPT_TEMPLATE_B64)["publicFiles"]
                        if label == "table012" else
                        [row for row in self._decode_operator_template(TRUSS011_RECEIPT_TEMPLATE_B64)["outputFiles"]
                         if row["path"] not in TRUSS011_TEMPLATE_SELECTED])
            digest_map = {old["sha256"]: row_by_path[old["path"]]["sha256"]
                          for old in old_rows if old["path"] in row_by_path}
            def rewrite(value):
                if isinstance(value, dict):
                    return {key: rewrite(item) for key, item in value.items()}
                if isinstance(value, list):
                    return [rewrite(item) for item in value]
                if isinstance(value, str):
                    if value.startswith(original_prefix + "/"):
                        return new_prefix + value[len(original_prefix):]
                    return digest_map.get(value, value)
                return value
            receipt_value = rewrite(receipt_value)
            # Reapply generated browser digest values after the general reference map.
            if label == "truss011":
                for lane, expected in expected_lanes.items():
                    facts = receipt_value["browserInputCustodyBeforeAfter"][lane]
                    expected["corpusSha256"] = facts["corpusSha256"]
                    for key, val in expected.items():
                        facts[key] = val
                    facts["postBrowserReceiptsSha256"] = facts["browserReceiptsSha256"]
                    facts["postBrowserSummarySha256"] = facts["browserSummarySha256"]
                    facts["postBrowserNativeReportSha256"] = facts["nativeReportSha256"]
            receipt_path = root / "operator-result.json"
            raw = (json.dumps(receipt_value, sort_keys=True, separators=(",", ":")) + "\n").encode()
            receipt_path.write_bytes(raw)
            receipt_ref = {"path": receipt_path.relative_to(self.root).as_posix(),
                           "sizeBytes": len(raw), "sha256": sha(raw)}
            phrase = ("ACCEPT the completed local Linux table-operations boundary evidence"
                      if label == "table012" else
                      "ACCEPTED scoped full local Truss facts/entity lane PASS")
            review = ref(self.root, f"reviews/{label}-accepted.md",
                         (phrase + "\n" + receipt_ref["sha256"] + "\n").encode())
            roots[prefix + "_ROOT"] = historical_copy_root
            digests[gate_name], review_digests[gate_name] = receipt_ref["sha256"], review["sha256"]
            gate_refs[gate_name] = {"receipt": receipt_ref, "review": review}
        gate_refs["linux-wasm"] = dict(gate_refs["linux-browser"])
        digests["linux-wasm"] = digests["linux-browser"]
        review_digests["linux-wasm"] = review_digests["linux-browser"]
        return {"roots": roots, "gateReceiptDigests": digests,
                "gateReviewDigests": review_digests, "tableReviewSha": review_digests["linux-inherited-boundaries"],
                "trussReviewSha": review_digests["linux-browser"],
                "tableSelected": validator.TABLE012_SELECTED,
                "trussSelected": validator.TRUSS011_SELECTED,
                "tableSelectedBytes": validator.TABLE012_SELECTED_BYTES,
                "trussSelectedBytes": validator.TRUSS011_SELECTED_BYTES,
                "tableSoftwareRoot": validator.TABLE012_SOFTWARE_ROOT,
                "trussSoftwareRoot": validator.TRUSS011_SOFTWARE_ROOT,
                "trussOutputBytes": validator.TRUSS011_OUTPUT_BYTES,
                "trussExpectedLanes": expected_lanes}

    def build(self) -> tuple[Path, list]:
        p_commit, p_tree, m_commit, m_tree = "a" * 40, "b" * 40, "c" * 40, "d" * 40
        metadata_base = {
            path: (f"test-only metadata bytes for {path}\n".encode())
            for path in validator.METADATA_ONLY_PATHS}
        metadata_m = dict(metadata_base)
        metadata_m["docs/helix/05-deploy/README.md"] = b"metadata-only"
